/* The code page 437 byte for a Unicode character, or -1 */
int cp437_from_ucs(unsigned long u)
{
    int lo = 0, hi = (int)(sizeof ucs / sizeof ucs[0]) - 1;

    if (u < 0x80)
        return (int)u;
    if (u > 0xFFFF)
        return -1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;

        if (ucs[mid] == u)
            return cp[mid];
        if (ucs[mid] < u)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return -1;
}
